@lru_cache(maxsize=1)
def _table():
    raw=zlib.decompress(base64.b85decode(_DATA))
    return dict(struct.iter_unpack('<Qb',raw))

def lookup(own,mask):
    key=own+mask
    mirrored=sum(((key>>(7*c))&127)<<(7*(6-c)) for c in range(7))
    return _table().get(min(key,mirrored))
